    "footerHtml": "<p>Each place distinguishes the source for its scene from the source for its position. Listed buildings use official WGS84 coordinates, identifying a building or monument rather than a character’s position inside it. Vanished addresses, street sections and areas have approximate references explained in the record. Decimal places do not guarantee metric accuracy.</p><p>The 1904 routes and addresses are checked against <em>James Joyce’s Dublin</em> by Ian Gunn and Clive Hart, with Harald Beck, revised edition 2022. Multi-character chapters show simultaneous scenes and different journeys. These are not present-day walking routes: points are not joined by lines that would cross buildings or reclaimed land. Memories and hallucinations are not measurable journeys.</p><p>Esri basemaps, including aerial and satellite imagery, depict contemporary geography. Dublin’s transformations prevent imagery from serving as a reconstruction of 1904. Sources were consulted on 7 October 2026; some historical locations still need refinement and are flagged.</p><p><a href=\"https://www.gutenberg.org/ebooks/4300\" target=\"_blank\" rel=\"noopener noreferrer\">Joyce · original text</a> · <a href=\"https://riverrun.org.uk/JJD2.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Gunn, Hart and Beck · topographical gazetteer</a> · <a href=\"https://data.gov.ie/dataset/national-inventory-of-architectural-heritage-niah-national-dataset\" target=\"_blank\" rel=\"noopener noreferrer\">NIAH · official building data</a> · <a href=\"https://data.gov.ie/dataset/dun-laoghaire-rathdown-record-of-protected-structures\" target=\"_blank\" rel=\"noopener noreferrer\">DLR County Council · protected structures</a> · <a href=\"https://www.jjon.org/\" target=\"_blank\" rel=\"noopener noreferrer\">James Joyce Online Notes</a></p><p><a href=\"places-en.csv\" download>Download the catalogue of places and sources</a></p>",
