              "quote": "[…] though misbelieving men nie that this be possible thing without they see it natheless they are so. And these fishes lie in an oily water brought there from Portugal land because of the fatness that therein is like to the juices of the olivepress. And also it was a marvel to see in that castle how by magic they make a compost out of fecund wheatkidneys out of Chaldee that by aid of certain angry spirits that they do in to it swells up wondrously like to a vast mountain. And they teach the serpents there to entwine themselves up on long sticks out of the ground and of the scales of these serpents they brew out […]",
